#include <vector>
using namespace std;

class Solution {
public:
    int waysToMakeFair(vector<int>& nums) {
        int total_even = 0, total_odd = 0;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0) total_even += nums[i];
            else total_odd += nums[i];
        }
        int pref_even = 0, pref_odd = 0, ans = 0;
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            if (i % 2 == 0) {
                int suff_even = total_even - pref_even - x;
                int suff_odd = total_odd - pref_odd;
                if (pref_even + suff_odd == pref_odd + suff_even) ans++;
                pref_even += x;
            } else {
                int suff_even = total_even - pref_even;
                int suff_odd = total_odd - pref_odd - x;
                if (pref_even + suff_odd == pref_odd + suff_even) ans++;
                pref_odd += x;
            }
        }
        return ans;
    }
};

